INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105465017', '{"id":"ad-105465017","title":{"ro":"Teren agricol de 118 ari în Stăuceni","ru":"Участок 118 соток под с/х в Стэученах","en":"1.18 ha of farmland in Stăuceni"},"deal":"sale","type":"land","price":670000,"exchangeFor":{"ro":"Schimb parțial pe automobil până la 50 000 €.","ru":"Частичный обмен на авто до 50 000 €.","en":"Partial exchange for a car up to €50,000."},"city":"chisinau","address":"s. Stăuceni, traseul Chișinău – Criuleni","area":11800,"rooms":0,"description":{"ro":"Teren agricol de 118 ari la marginea satului Stăuceni, lângă traseul Chișinău – Criuleni.","ru":"Сельхозучасток 118 соток на окраине Стэучен, у трассы Кишинёв – Криуляны.","en":"A 1.18 ha agricultural plot on the edge of Stăuceni, by the Chișinău – Criuleni road."},"images":["/listings/ad-105465017/1.jpg","/listings/ad-105465017/2.jpg","/listings/ad-105465017/3.jpg","/listings/ad-105465017/4.jpg","/listings/ad-105465017/5.jpg","/listings/ad-105465017/6.jpg","/listings/ad-105465017/7.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104276527', '{"id":"ad-104276527","title":{"ro":"6 ari pentru construcție în Vatra, lângă pădure","ru":"6 соток под строительство в Ватре, у леса","en":"6-are building plot in Vatra, by the forest"},"deal":"sale","type":"land","price":71500,"city":"chisinau","address":"or. Vatra, cooperativa Apicultorul","area":600,"rooms":0,"description":{"ro":"Teren de 6 ari în cooperativa Apicultorul din Vatra. În jur — pădure.","ru":"Участок 6 соток в дачном кооперативе «Апикултурул», Ватра. Вокруг лес.","en":"A 600 m² plot in the Apicultorul cooperative in Vatra, surrounded by forest."},"images":["/listings/ad-104276527/1.jpg","/listings/ad-104276527/2.jpg","/listings/ad-104276527/3.jpg","/listings/ad-104276527/4.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105737463', '{"id":"ad-105737463","title":{"ro":"Clădire istorică de 300 m² în centru — Casa Masonică","ru":"Историческое здание 300 м² в центре — Масонский дом","en":"300 m² historic building in the centre — the Masonic House"},"deal":"rent","type":"commercial","price":4000,"city":"chisinau","address":"str. 31 August 1989, Centru","area":300,"rooms":0,"description":{"ro":"O clădire unică — singura de acest fel în Chișinău. Casa Masonică, construită în 1892. Chirie pe termen lung. Parcare și curte interioară.","ru":"Уникальное здание — единственное такое в Кишинёве. Масонский дом, год постройки 1892. Аренда долгосрочная. Парковка, внутренний двор.","en":"A unique building — the only one of its kind in Chișinău. The Masonic House, built in 1892. Long-term lease. Parking and an inner courtyard."},"images":["/listings/ad-105737463/1.jpg","/listings/ad-105737463/2.jpg","/listings/ad-105737463/3.jpg","/listings/ad-105737463/4.jpg","/listings/ad-105737463/5.jpg","/listings/ad-105737463/6.jpg","/listings/ad-105737463/7.jpg","/listings/ad-105737463/8.jpg","/listings/ad-105737463/9.jpg","/listings/ad-105737463/10.jpg"],"features":["parking","nearCenter"],"contactName":"","contactPhone":"","createdAt":"2026-10-31","featured":true}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105775277', '{"id":"ad-105775277","title":{"ro":"Bază de odihnă pe 7,5 ha pe malul lacului","ru":"База отдыха на 7,5 га на берегу озера","en":"Leisure base on 7.5 ha on a lakeshore"},"deal":"sale","type":"commercial","price":300000,"exchangeFor":{"ro":"Schimb pe automobil, imobil sau materiale de construcție până la 50 000 €.","ru":"Обмен на авто, недвижимость или стройматериалы до 50 000 €.","en":"Exchange for a car, property or building materials up to €50,000."},"city":"chisinau","address":"la 20 de minute de Botanica","area":750,"rooms":0,"description":{"ro":"7,5 ha pe malul lacului, clădiri de 750 m². Fântână arteziană și transformator propriu. Mănăstire în apropiere. La 20 de minute de Botanica.","ru":"7,5 га на берегу озера, строения 750 м². Артезианская скважина, трансформатор. Рядом монастырь. 20 минут от Ботаники.","en":"7.5 ha on a lakeshore with 750 m² of buildings. Artesian well and its own transformer. A monastery nearby. 20 minutes from Botanica."},"images":["/listings/ad-105775277/1.jpg","/listings/ad-105775277/2.jpg","/listings/ad-105775277/3.jpg","/listings/ad-105775277/4.jpg","/listings/ad-105775277/5.jpg","/listings/ad-105775277/6.jpg","/listings/ad-105775277/7.jpg"],"features":["waterView"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
