INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105736213', '{"id":"ad-105736213","title":{"ro":"6 ari în Codru — pentru casă, duplex sau triplex","ru":"6 соток в Кодру — под дом, дуплекс или триплекс","en":"6 ares in Codru — for a house, duplex or triplex"},"deal":"sale","type":"land","price":235000,"city":"chisinau","address":"or. Codru, str. Sfîntul Gheorghe","area":600,"rooms":0,"description":{"ro":"Toate comunicațiile la hotar. În fața terenului — locuri de parcare. Potrivit pentru o casă, un duplex sau un triplex.","ru":"Все коммуникации на границе. Перед участком парковочные места. Под дом, дуплекс или триплекс.","en":"All utilities at the boundary and parking spaces in front of the plot. Suitable for a house, duplex or triplex."},"images":["/listings/ad-105736213/1.jpg","/listings/ad-105736213/2.jpg","/listings/ad-105736213/3.jpg","/listings/ad-105736213/4.jpg","/listings/ad-105736213/5.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
