INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105667430', '{"id":"ad-105667430","title":{"ro":"1 ha pentru construcție, Calea Ghidighiciului","ru":"1 гектар под строительство, Калea Гидигичулуй","en":"1 ha building land on Calea Ghidighiciului"},"deal":"sale","type":"land","price":500000,"city":"chisinau","address":"Sculeanca, str. Calea Ghidighiciului","area":10000,"rooms":0,"description":{"ro":"Teren agricol cu bonitate de 30%, ceea ce permite, la nevoie, schimbarea destinației terenului.","ru":"Земля аграрная, бонитет 30% — это позволяет при необходимости изменить статус земли.","en":"Agricultural land with a 30% soil rating, which allows its designation to be changed if needed."},"images":["/listings/ad-105667430/1.jpg","/listings/ad-105667430/2.jpg","/listings/ad-105667430/3.jpg","/listings/ad-105667430/4.jpg","/listings/ad-105667430/5.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105737614', '{"id":"ad-105737614","title":{"ro":"IT-sat: 25 ha cu lac, mini-hotel și 8 iurte","ru":"IT-поселение: 25 га с озером, мини-отелем и 8 юртами","en":"IT village: 25 ha with a lake, a mini hotel and 8 yurts"},"deal":"sale","type":"commercial","price":950000,"exchangeFor":{"ro":"Schimb parțial pe imobil în Chișinău.","ru":"Частичный обмен на недвижимость в Кишинёве.","en":"Partial exchange for property in Chișinău."},"city":"moldova","address":"","area":250000,"rooms":0,"description":{"ro":"Prețul de 950 000 € include: apă, electricitate, canalizare, drum; 25 ha de teren; mini-hotel; 8 iurte. În proprietate — lac cu pește, pădure, câmpuri, vânat.","ru":"Стоимость 950 000 € включает: вода, электричество, канализация, дорога; 25 га земли; мини-отель; 8 юрт. В собственности — озеро с рыбой, лес, поля, дичь.","en":"The €950,000 price includes water, electricity, sewage and road access; 25 ha of land; a mini hotel; 8 yurts. The property has a lake with fish, forest, fields and game."},"images":["/listings/ad-105737614/1.jpg","/listings/ad-105737614/2.jpg","/listings/ad-105737614/3.jpg","/listings/ad-105737614/4.jpg","/listings/ad-105737614/5.jpg","/listings/ad-105737614/6.jpg","/listings/ad-105737614/7.jpg","/listings/ad-105737614/8.jpg","/listings/ad-105737614/9.jpg","/listings/ad-105737614/10.jpg"],"features":["waterView"],"contactName":"","contactPhone":"","createdAt":"2026-10-31","featured":true}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105703237', '{"id":"ad-105703237","title":{"ro":"2 ha de teren cu pădure în Bacioi","ru":"2 гектара лесного участка в Бачое","en":"2 ha of woodland in Bacioi"},"deal":"sale","type":"land","price":28000,"city":"chisinau","address":"s. Bacioi, la margine","area":20000,"rooms":0,"description":{"ro":"Se poate vinde de la 50 până la 200 de ari. Pădure, lac, traseu, bază de odihnă în apropiere. Loc frumos. Se poate aduce electricitatea și face o fântână. Pentru proiecte agricole și altele.","ru":"Можно продать от 50 до 200 соток. Лес, озеро, трасса, база отдыха рядом. Красивое место. Можно подтянуть электричество, сделать колодец. Под с/х проекты и другое.","en":"Can be sold in parts from 0.5 to 2 ha. Forest, a lake, the highway and a leisure base nearby. A beautiful spot. Electricity can be brought in and a well dug. Suits farming and other projects."},"images":["/listings/ad-105703237/1.jpg","/listings/ad-105703237/2.jpg","/listings/ad-105703237/3.jpg","/listings/ad-105703237/4.jpg"],"features":["waterView"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104826794', '{"id":"ad-104826794","title":{"ro":"2,4 ha între Nistru și pădure, cu lacuri","ru":"2,4 га между Днестром и лесом, с озёрами","en":"2.4 ha between the Dniester and the forest, with ponds"},"deal":"sale","type":"land","price":149000,"exchangeFor":{"ro":"Schimb pe imobil sau automobil.","ru":"Обмен на недвижимость или автомобиль.","en":"Exchange for property or a car."},"city":"aneniiNoi","address":"lângă Nistru, la 7 km de Castelul Mimi","area":24000,"rooms":0,"description":{"ro":"Teren agricol de 2,4 ha între Nistru și pădure. Un lac mare și două mici (apa este scursă), se umplu cu pompă din Nistru. La 50 km de Chișinău și 7 km de Castelul Mimi. Drum bun.","ru":"Сельхозземля 2,4 га между Днестром и лесом. Одно большое озеро и два маленьких (вода спущена), при необходимости наполняются насосом из Днестра. 50 км от Кишинёва, 7 км от замка Мими. Хорошая дорога.","en":"2.4 ha of farmland between the Dniester and a forest. One large and two small ponds (currently drained) that can be refilled by pump from the river. 50 km from Chișinău, 7 km from Mimi Castle. Good road."},"images":["/listings/ad-104826794/1.jpg","/listings/ad-104826794/2.jpg","/listings/ad-104826794/3.jpg","/listings/ad-104826794/4.jpg","/listings/ad-104826794/5.jpg"],"features":["waterView"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
