INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105434516', '{"id":"ad-105434516","title":{"ro":"50 ari: 8 loturi a câte 6 ari, la 10 km de Botanica","ru":"50 соток: 8 участков по 6 соток, 10 км от Ботаники","en":"50 ares: 8 plots of 6 ares, 10 km from Botanica"},"deal":"sale","type":"land","price":99000,"city":"chisinau","address":"zona Aeroport, la 10 km de Botanica","area":5000,"rooms":0,"description":{"ro":"La 10 km de Botanica. 8 loturi a câte 6 ari. Drum, apă și electricitate la hotar. Gaz și canalizare — la 300 m.","ru":"В 10 км от Ботаники. 8 участков по 6 соток каждый. Дорога, вода и электричество на границе. Газ, канализация — 300 м.","en":"10 km from Botanica. Eight plots of 600 m² each. Road, water and electricity at the boundary; gas and sewage 300 m away."},"images":["/listings/ad-105434516/1.jpg","/listings/ad-105434516/2.jpg","/listings/ad-105434516/3.jpg","/listings/ad-105434516/4.jpg","/listings/ad-105434516/5.jpg","/listings/ad-105434516/6.jpg","/listings/ad-105434516/7.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104396312', '{"id":"ad-104396312","title":{"ro":"128 ari de teren agricol în Condrița","ru":"128 соток под с/х в Кондрице","en":"1.28 ha of farmland in Condrița"},"deal":"sale","type":"land","price":225000,"city":"chisinau","address":"s. Condrița, la margine","area":12800,"rooms":0,"description":{"ro":"Teren agricol de 128 de ari la marginea satului Condrița, lângă codrii.","ru":"Сельхозучасток 128 соток на окраине Кондрицы, рядом Кодры.","en":"A 1.28 ha agricultural plot on the edge of Condrița, near the Codri forests."},"images":["/listings/ad-104396312/1.jpg","/listings/ad-104396312/2.jpg","/listings/ad-104396312/3.jpg","/listings/ad-104396312/4.jpg","/listings/ad-104396312/5.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104826582', '{"id":"ad-104826582","title":{"ro":"Uscătorie de fructe și legume pe 0,94 ha, Pugăceni","ru":"Сушилка для фруктов и овощей на 0,94 га, Пугачёны","en":"Fruit and vegetable drying plant on 0.94 ha, Pugăceni"},"deal":"sale","type":"commercial","price":165000,"exchangeFor":{"ro":"Schimb parțial pe automobil până la 35 000 €.","ru":"Частичный бартер на авто до 35 000 €.","en":"Partial exchange for a car up to €35,000."},"city":"aneniiNoi","address":"s. Pugăceni","area":878,"rooms":0,"description":{"ro":"Se vinde o uscătorie de fructe și legume. Comunicațiile și capacitățile permit dezvoltarea mai multor direcții.\n\nTeren 0,94 ha. Clădire 878 m², 2 cuptoare (13 m) cu 2 generatoare VPT600, arzătoare italiene pe gaz, zonă de producție, prelucrare, sortare și depozit subteran. Casă de 125 m² (oficiu, cazare pentru personal, pază). Fântână arteziană, turn de apă, gazoduct de presiune medie și joasă, transformator de 160 kW. La 60 km de Chișinău.\n\nVolume: cireșe și vișine — 40 t pe an, mere de vară — 28–35 t, prune — 120–160 t. Prețul include TVA.","ru":"Продаётся сушилка для фруктов и овощей. Коммуникации и мощности позволяют развивать разные направления.\n\nЗемля 0,94 га. Здание 878 м², 2 печи (13 м) с 2 генераторами VPT600, итальянские газовые форсунки, производственный участок, участки переработки и сортировки, подвальное хранилище. Дом 125 м² (офис, жильё для персонала, охрана). Артезианская скважина, водонапорная башня, газопровод среднего и низкого давления, трансформатор 160 кВт. 60 км от Кишинёва.\n\nОбъёмы: вишня и черешня — 40 т в год, летние яблоки — 28–35 т, сливы — 120–160 т. Цена с НДС.","en":"A fruit and vegetable drying plant whose utilities and capacity allow for other lines of business.\n\n0.94 ha of land. An 878 m² building with two 13 m kilns and two VPT600 generators, Italian gas burners, production, processing and sorting areas and a cellar store. A 125 m² house (office, staff housing, security). Artesian well, water tower, medium- and low-pressure gas, 160 kW transformer. 60 km from Chișinău.\n\nOutput: cherries — 40 t a year, summer apples — 28–35 t, plums — 120–160 t. Price includes VAT."},"images":["/listings/ad-104826582/1.jpg","/listings/ad-104826582/2.jpg","/listings/ad-104826582/3.jpg","/listings/ad-104826582/4.jpg","/listings/ad-104826582/5.jpg","/listings/ad-104826582/6.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103899220', '{"id":"ad-103899220","title":{"ro":"7,4 ha pe prima linie a traseului Budești – Vadul lui Vodă","ru":"7,4 га на первой линии трассы Будешты – Вадул-луй-Водэ","en":"7.4 ha fronting the Budești – Vadul lui Vodă road"},"deal":"sale","type":"land","price":740000,"city":"chisinau","address":"traseul Budești – Vadul lui Vodă, prima linie","area":74000,"rooms":0,"description":{"ro":"1 000 € pe ar. Teren pe prima linie a traseului Budești – Vadul lui Vodă. Acces la electricitate și apă.","ru":"1 000 € за сотку. Участок на первой линии трассы Будешты – Вадул-луй-Водэ. Доступ к электричеству и воде.","en":"€1,000 per are (100 m²). A plot fronting the Budești – Vadul lui Vodă road. Electricity and water available."},"images":["/listings/ad-103899220/1.jpg","/listings/ad-103899220/2.jpg","/listings/ad-103899220/3.jpg","/listings/ad-103899220/4.jpg","/listings/ad-103899220/5.jpg","/listings/ad-103899220/6.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105541474', '{"id":"ad-105541474","title":{"ro":"Vilă modulară + 7 ari, la 15 minute de Buiucani","ru":"Дача + 7 соток, 15 минут от Буюкан","en":"Modular cabin + 7 ares, 15 minutes from Buiucani"},"deal":"sale","type":"house","price":45000,"city":"chisinau","address":"Dumbrava, Alfa-Agro, la 15 min de Buiucani","area":18,"rooms":0,"description":{"ro":"Casă modulară din panouri sandwich de 18 m², complet mobilată. Baie complet utilată: cabină de duș, WC, chiuvetă. Instalație electrică, Smart TV, aer condiționat pentru vară și iarnă, încălzire, boiler. Pat dublu și canapea extensibilă. Ferestre panoramice. Gata de folosit tot anul, fără investiții suplimentare.\n\nTerenul fără casă — 25 000 €.","ru":"Модульный дом из сэндвич-панелей 18 м², полностью меблирован. Полностью оборудованная ванная: душевая кабина, туалет, раковина. Электрика, Smart TV, кондиционер на лето и зиму, отопление, водонагреватель. Двуспальная кровать и диван-кровать. Панорамные окна. Готов к использованию круглый год, без дополнительных вложений.\n\nУчасток без дома — 25 000 €.","en":"An 18 m² sandwich-panel modular cabin, fully furnished. A fully equipped bathroom with shower, toilet and sink. Wiring, Smart TV, heat-pump air conditioning, heating and a water heater. Double bed and sofa bed. Panoramic windows. Ready for year-round use with no further investment.\n\nThe plot without the cabin is €25,000."},"images":["/listings/ad-105541474/1.jpg","/listings/ad-105541474/2.jpg","/listings/ad-105541474/3.jpg","/listings/ad-105541474/4.jpg","/listings/ad-105541474/5.jpg"],"features":["furniture","ac","heating"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103647451', '{"id":"ad-103647451","title":{"ro":"Casă cu mini-fermă de peste 500 m² în Lozova","ru":"Дом с мини-фермой более 500 м² в Лозово","en":"House with a mini farm, over 500 m², in Lozova"},"deal":"sale","type":"house","price":43000,"city":"straseni","address":"s. Lozova, lângă rezervația Codrii","area":500,"rooms":0,"description":{"ro":"Lozova, în jur — rezervația Codrii. Casă și mini-fermă, peste 500 m². Casa necesită reparație, dar construcția e capitală (beton, piatră, cotileț). Electricitate, apă, canalizare, gaz, telefon, drum asfaltat. Teren de 9,4 ari. Margine de sat, priveliște frumoasă spre Codri.","ru":"Лозово, вокруг резервация Кодры. Дом + мини-ферма, более 500 м². Дом требует ремонта, но конструкция капитальная (бетон, бут, котелец). Электричество, вода, канализация, газ, телефон, асфальтированная дорога. Участок 9,4 сотки. Окраина, красивый вид на Кодры.","en":"Lozova, surrounded by the Codri nature reserve. A house and mini farm of over 500 m². The house needs renovation but is solidly built (concrete and stone). Electricity, water, sewage, gas, phone and a paved road. 940 m² plot on the edge of the village with a lovely view of the Codri."},"images":["/listings/ad-103647451/1.jpg","/listings/ad-103647451/2.jpg","/listings/ad-103647451/3.jpg","/listings/ad-103647451/4.jpg","/listings/ad-103647451/5.jpg","/listings/ad-103647451/6.jpg","/listings/ad-103647451/7.jpg","/listings/ad-103647451/8.jpg","/listings/ad-103647451/9.jpg","/listings/ad-103647451/10.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104826708', '{"id":"ad-104826708","title":{"ro":"Club sportiv în centru — profit 2 500 € pe lună","ru":"Спорт-клуб в центре — прибыль 2 500 € в месяц","en":"Sports club in the centre — €2,500 monthly profit"},"deal":"sale","type":"commercial","price":52000,"city":"chisinau","address":"Centru, în spatele Guvernului","area":200,"rooms":0,"description":{"ro":"Afacere funcțională. Profit net mediu — 2 500 € pe lună. Centru, în spatele Guvernului, se învecinează cu un bazin (acces la bazin și saună).\n\nPrețul include: persoana juridică (casa de marcat, contractul de chirie pentru 200 m²), tot echipamentul, mobila și tehnica. Imobilul este în chirie. Vânzătorul este gata să continue administrarea. Posibilități de dezvoltare datorită vecinilor: bazin, terenuri de tenis, saună. Vânzare de nutriție sportivă.","ru":"Действующий бизнес. Чистая прибыль в среднем 2 500 € в месяц. Центр, за правительством, граничит с бассейном (есть вход в бассейн и сауну).\n\nСтоимость включает: юридическое лицо (кассовый аппарат, контракт аренды на 200 м²), всё оборудование, мебель, технику. Помещение в аренде. Готов продолжить администрирование. Есть возможности для развития с учётом соседей: бассейн, теннисные корты, сауна. Продажа спортивного питания.","en":"A running business with an average net profit of €2,500 a month. In the centre behind the Government building, next to a swimming pool (with access to the pool and sauna).\n\nThe price includes the company (cash register, lease for 200 m²), all equipment, furniture and appliances. The premises are leased. The seller is willing to stay on as manager. Room to grow alongside the pool, tennis courts and sauna next door. Sports nutrition sales."},"images":["/listings/ad-104826708/1.jpg"],"features":["nearCenter","pool"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105542407', '{"id":"ad-105542407","title":{"ro":"15 ari în Bubuieci cu toate comunicațiile","ru":"15 соток в Бубуечь со всеми коммуникациями","en":"15 ares in Bubuieci with all utilities"},"deal":"sale","type":"land","price":117000,"city":"chisinau","address":"s. Bubuieci, str. Școlii","area":1500,"rooms":0,"description":{"ro":"Gaz, apă, electricitate și canalizare pe teren, plus fântână. Casă pentru demolare.","ru":"Газ, вода, электричество, канализация на участке, плюс колодец. Дом под снос.","en":"Gas, water, electricity and sewage on the plot, plus a well. The existing house is for demolition."},"images":["/listings/ad-105542407/1.jpg","/listings/ad-105542407/2.jpg","/listings/ad-105542407/3.jpg","/listings/ad-105542407/4.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105704754', '{"id":"ad-105704754","title":{"ro":"Hotel în centru: 12 etaje, 200 de camere","ru":"Отель в центре: 12 этажей, 200 номеров","en":"Hotel in the centre: 12 floors, 200 rooms"},"deal":"sale","type":"commercial","price":5300000,"city":"chisinau","address":"str. Anton Pann, Centru","area":6100,"rooms":0,"description":{"ro":"Pentru investitori. Teren de 30 de ari, clădire de 6 100 m², 12 etaje, 200 de camere. Sală de conferințe, cafenea, bar.","ru":"Инвестору. Земельный участок 30 соток, здание 6 100 м², 12 этажей, 200 номеров. Конференц-зал, кафе, бар.","en":"For investors. A 3,000 m² plot with a 6,100 m² building: 12 floors, 200 rooms, a conference hall, café and bar."},"images":["/listings/ad-105704754/1.jpg","/listings/ad-105704754/2.jpg","/listings/ad-105704754/3.jpg","/listings/ad-105704754/4.jpg","/listings/ad-105704754/5.jpg"],"features":["nearCenter","elevator","parking"],"contactName":"","contactPhone":"","createdAt":"2026-10-31","featured":true}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105759285', '{"id":"ad-105759285","title":{"ro":"Oficiu de 70 m² vizavi de Ambasada SUA","ru":"Офис 70 м² напротив посольства США","en":"70 m² office opposite the US Embassy"},"deal":"rent","type":"commercial","price":2000,"city":"chisinau","address":"str. Alexei Mateevici, Centru","area":70,"rooms":0,"description":{"ro":"Oficiu de 70 m² pe str. Alexei Mateevici, vizavi de Ambasada SUA.","ru":"Офис 70 м² на ул. Алексея Матеевича, напротив посольства США.","en":"A 70 m² office on Alexei Mateevici Street, opposite the US Embassy."},"images":["/listings/ad-105759285/1.jpg","/listings/ad-105759285/2.jpg","/listings/ad-105759285/3.jpg","/listings/ad-105759285/4.jpg","/listings/ad-105759285/5.jpg","/listings/ad-105759285/6.jpg","/listings/ad-105759285/7.jpg"],"features":["nearCenter"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105738044', '{"id":"ad-105738044","title":{"ro":"Spațiu comercial cu chiriași — 2 000 € pe lună","ru":"Коммерческое помещение с арендаторами — 2 000 € в месяц","en":"Commercial premises with tenants — €2,000 a month"},"deal":"sale","type":"commercial","price":250000,"city":"chisinau","address":"","area":0,"rooms":0,"description":{"ro":"Acum un spațiu aduce 1 400 € pe lună. Al doilea, după reparație, va fi dat în chirie pentru 750–850 € pe lună. Parcare.","ru":"На данный момент одно помещение приносит 1 400 € в месяц. Второе после ремонта планируется сдавать за 750–850 € в месяц. Парковка.","en":"One unit currently earns €1,400 a month. The second, after renovation, is expected to rent for €750–850 a month. Parking."},"images":["/listings/ad-105738044/1.jpg","/listings/ad-105738044/2.jpg","/listings/ad-105738044/3.jpg","/listings/ad-105738044/4.jpg","/listings/ad-105738044/5.jpg","/listings/ad-105738044/6.jpg","/listings/ad-105738044/7.jpg"],"features":["parking"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105572751', '{"id":"ad-105572751","title":{"ro":"3 ha la traseul național Chișinău – Ungheni","ru":"3 га у трассы Кишинёв – Унгены","en":"3 ha on the Chișinău – Ungheni highway"},"deal":"sale","type":"land","price":345000,"exchangeFor":{"ro":"Schimb parțial pe automobil până la 50 000 €.","ru":"Частичный обмен на авто до 50 000 €.","en":"Partial exchange for a car up to €50,000."},"city":"chisinau","address":"traseul Chișinău – Ungheni, la 20 km de Chișinău","area":30000,"rooms":0,"description":{"ro":"Traseul național Chișinău – Ungheni, la 20 km de Chișinău. 227 m de-a lungul drumului, 115 m în adâncime. Proiect de apă aprobat (600 m).","ru":"Национальная трасса Кишинёв – Унгены, 20 км от Кишинёва. 227 м вдоль дороги, 115 м в глубину. Согласован проект на воду (600 м).","en":"On the Chișinău – Ungheni national highway, 20 km from Chișinău. 227 m of road frontage, 115 m deep. Approved water connection project (600 m)."},"images":["/listings/ad-105572751/1.jpg","/listings/ad-105572751/2.jpg","/listings/ad-105572751/3.jpg","/listings/ad-105572751/4.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105569240', '{"id":"ad-105569240","title":{"ro":"Spațiu de producție de 10 000 m² în ZEL Comrat","ru":"Производственное помещение 10 000 м² в СЭЗ Комрат","en":"10,000 m² production facility in the Comrat free economic zone"},"deal":"sale","type":"commercial","price":5000000,"city":"comrat","address":"ZEL Comrat","area":10000,"rooms":0,"description":{"ro":"Comrat, zona economică liberă. 10 000 m². Vânzare — 5 000 000 €, chirie — 5 € pe m².","ru":"Комрат, СЭЗ. 10 000 м². Продажа — 5 000 000 €, аренда — 5 € за м².","en":"Comrat, free economic zone. 10,000 m². For sale at €5,000,000 or for rent at €5 per m²."},"images":["/listings/ad-105569240/1.jpg","/listings/ad-105569240/2.jpg","/listings/ad-105569240/3.jpg","/listings/ad-105569240/4.jpg","/listings/ad-105569240/5.jpg","/listings/ad-105569240/6.jpg","/listings/ad-105569240/7.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104839781', '{"id":"ad-104839781","title":{"ro":"Spațiu de 200 m² în centru, str. A. Hâjdeu","ru":"Помещение 200 м² в центре, ул. А. Хаждеу","en":"200 m² premises in the centre, A. Hâjdeu Street"},"deal":"sale","type":"commercial","price":200000,"city":"chisinau","address":"str. Alexandru Hâjdeu 110, Centru","area":200,"rooms":0,"description":{"ro":"1 000 € pe m². Se vinde de la 189 până la 650 m², în trei părți:\n• 204,7 m² — intrare separată din drum, ieșire în curte, contoare intermediare, baie;\n• 189,5 m² — intrare separată din stradă, contoare principale de apă, gaz și electricitate, baie;\n• 262,2 m² — intrare separată, ieșire în curte, cazan pe gaz propriu, baie.\n\nApă, canalizare, ventilație, încălzire autonomă. Spațiu uscat și cald. Pardoseală din gresie. Demisolul unui bloc cu patru etaje.","ru":"1 000 € за м². Возможна продажа от 189 до 650 м², три части:\n• 204,7 м² — отдельный вход с дороги, выход во двор, промежуточные счётчики, санузел;\n• 189,5 м² — отдельный вход с улицы, основные счётчики воды, газа и электричества, санузел;\n• 262,2 м² — отдельный вход, выход во двор, свой газовый котёл, санузел.\n\nВода, канализация, вентиляция, автономное отопление. Сухое, тёплое помещение. Пол — плитка. Цокольный этаж четырёхэтажного дома.","en":"€1,000 per m². Available from 189 to 650 m², in three parts:\n• 204.7 m² — own entrance from the road, courtyard exit, sub-meters, bathroom;\n• 189.5 m² — own street entrance, main water, gas and power meters, bathroom;\n• 262.2 m² — own entrance, courtyard exit, its own gas boiler, bathroom.\n\nWater, sewage, ventilation and individual heating. Dry and warm, tiled floors. Lower ground floor of a four-storey building."},"images":["/listings/ad-104839781/1.jpg","/listings/ad-104839781/2.jpg","/listings/ad-104839781/3.jpg","/listings/ad-104839781/4.jpg","/listings/ad-104839781/5.jpg","/listings/ad-104839781/6.jpg","/listings/ad-104839781/7.jpg","/listings/ad-104839781/8.jpg","/listings/ad-104839781/9.jpg"],"features":["heating","nearCenter"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103666839', '{"id":"ad-103666839","title":{"ro":"6 ari pe bd. Alba Iulia","ru":"6 соток на бул. Алба Юлия","en":"6 ares on Alba Iulia Boulevard"},"deal":"sale","type":"land","price":410000,"city":"chisinau","address":"bd. Alba Iulia 75/14","area":600,"rooms":0,"description":{"ro":"Teren pentru construcție de 6 ari, bd. Alba Iulia 75/14.","ru":"Участок 6 соток под строительство, бул. Алба Юлия 75/14.","en":"A 600 m² building plot at 75/14 Alba Iulia Boulevard."},"images":["/listings/ad-103666839/1.jpg","/listings/ad-103666839/2.jpg","/listings/ad-103666839/3.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104565875', '{"id":"ad-104565875","title":{"ro":"Casă cu 35 ari de teren în Bahmut","ru":"Дом с участком 35 соток в Бахмуте","en":"House with 35 ares of land in Bahmut"},"deal":"sale","type":"house","price":36000,"city":"calarasi","address":"s. Bahmut","area":73,"rooms":0,"description":{"ro":"Satul Bahmut. Teren de 35 de ari, casă de 73 m², bucătărie de vară de 26 m², foișor, bazin, șopron. Teren mare cu pomi fructiferi. Este posibilă cumpărarea în credit ipotecar.","ru":"Село Бахмут. Участок 35 соток, дом 73 м², летняя кухня 26 м², беседка, бассейн, сарай. Большой участок, плодовые деревья. Возможна покупка в ипотеку.","en":"Bahmut village. A 3,500 m² plot with a 73 m² house, a 26 m² summer kitchen, a gazebo, a pool and a shed. Large garden with fruit trees. Mortgage possible."},"images":["/listings/ad-104565875/1.jpg","/listings/ad-104565875/2.jpg","/listings/ad-104565875/3.jpg","/listings/ad-104565875/4.jpg","/listings/ad-104565875/5.jpg","/listings/ad-104565875/6.jpg","/listings/ad-104565875/7.jpg","/listings/ad-104565875/8.jpg","/listings/ad-104565875/9.jpg","/listings/ad-104565875/10.jpg"],"features":["pool","terrace"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105039055', '{"id":"ad-105039055","title":{"ro":"Fermă de 172 ha în Peresecina: livezi, lac, tehnică","ru":"Агроучасток 172 га в Пересечине: сады, водоём, техника","en":"172 ha farm in Peresecina: orchards, a reservoir, machinery"},"deal":"sale","type":"land","price":4300000,"city":"orhei","address":"s. Peresecina, la intrarea în sat, traseul R6","area":1720000,"rooms":0,"description":{"ro":"25 000 € pe hectar. Teren agricol de 172 ha la intrarea în satul Peresecina, raionul Orhei, la 20 km de Chișinău, cu ieșire la traseul R6, drum asfaltat.\n\nComponență: 50 ha teren nelucrat, 50 ha teren arabil, 49 ha livadă de caise, 10 ha livadă de vișini, 12 ha pădure de salcâm (15 ani), lac de acumulare de 1 ha cu posibilitate de extindere la 3 ha.\n\nÎmprejmuire, două intrări cu porți din traseu, posibilitate de conectare la rețeaua electrică, furtunuri de presiune de 2 km de la lac la livezi.\n\nTehnică: 3 tractoare, 4 stivuitoare, 2 tocătoare, 2 grape cu discuri, 2 aspersoare, cisterne, excavator pe tractor, pompă Landini.","ru":"25 000 € за гектар. Сельхозучасток 172 га на въезде в село Пересечина, Оргеевский район, 20 км от Кишинёва, съезд на трассу R6, асфальтированная дорога.\n\nСостав: 50 га необработанных угодий, 50 га пахотной земли, 49 га абрикосового сада, 10 га вишнёвого сада, 12 га акациевого леса (15 лет), водохранилище 1 га с возможностью расширения до 3 га.\n\nОграждение, два въезда с трассы с воротами, возможность подключения к электросети, шланги высокого давления 2 км от водоёма к садам.\n\nТехника: 3 трактора, 4 погрузчика, 2 измельчителя, 2 дисковые бороны, 2 дождевателя, цистерны, тракторный экскаватор, насос Landini.","en":"€25,000 per hectare. 172 ha of farmland at the entrance to Peresecina, Orhei district, 20 km from Chișinău, with access to the R6 highway by a paved road.\n\nMade up of 50 ha uncultivated land, 50 ha arable land, 49 ha apricot orchard, 10 ha cherry orchard, 12 ha of 15-year-old acacia forest and a 1 ha reservoir that can be enlarged to 3 ha.\n\nFenced, with two gated entrances from the highway, grid connection possible and 2 km of high-pressure hoses from the reservoir to the orchards.\n\nMachinery: 3 tractors, 4 forklifts, 2 mulchers, 2 disc harrows, 2 sprinklers, tanks, a tractor excavator and a Landini pump."},"images":["/listings/ad-105039055/1.jpg","/listings/ad-105039055/2.jpg"],"features":["waterView"],"contactName":"","contactPhone":"","createdAt":"2026-10-31","featured":true}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104714821', '{"id":"ad-104714821","title":{"ro":"136 ari pentru construcție, str. Sportivilor","ru":"136 соток под строительство, ул. Спортивилор","en":"1.36 ha building land on Sportivilor Street"},"deal":"sale","type":"land","price":575000,"city":"chisinau","address":"Sculeanca, str. Sportivilor","area":13600,"rooms":0,"description":{"ro":"Teren de 136 de ari pentru construcție, str. Sportivilor, Sculeanca. Număr cadastral 8039317.021.","ru":"Участок 136 соток под строительство, ул. Спортивилор, Скулянка. Кадастровый номер 8039317.021.","en":"A 1.36 ha building plot on Sportivilor Street, Sculeanca. Cadastral number 8039317.021."},"images":["/listings/ad-104714821/1.jpg","/listings/ad-104714821/2.jpg","/listings/ad-104714821/3.jpg","/listings/ad-104714821/4.jpg","/listings/ad-104714821/5.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
