INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105515940', '{"id":"ad-105515940","title":{"ro":"30 ari pe Șoseaua Poltava, la intrarea în Poiana Domnească","ru":"30 соток на Полтавском шоссе, у въезда в Poiana Domnească","en":"30 ares on Poltava Road, at the entrance to Poiana Domnească"},"deal":"sale","type":"land","price":690000,"exchangeFor":{"ro":"Schimb parțial pe automobil până la 100 000 €.","ru":"Частичный обмен на авто до 100 000 €.","en":"Partial exchange for a car up to €100,000."},"city":"chisinau","address":"Șoseaua Poltava, vizavi de PECO Sanatrix","area":3000,"rooms":0,"description":{"ro":"Șoseaua Poltava, vizavi de stația PECO Sanatrix, la intrarea în Poiana Domnească.","ru":"Полтавское шоссе, напротив АЗС Sanatrix, у въезда в Poiana Domnească.","en":"On Poltava Road, opposite the Sanatrix petrol station, at the entrance to Poiana Domnească."},"images":["/listings/ad-105515940/1.jpg","/listings/ad-105515940/2.jpg","/listings/ad-105515940/3.jpg","/listings/ad-105515940/4.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
