INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105577695', '{"id":"ad-105577695","title":{"ro":"6 ari cu proiect de casă lângă lac, Bacioi","ru":"6 соток с проектом дома у озера, Бачой","en":"6 ares with a house project by the lake, Bacioi"},"deal":"sale","type":"land","price":43000,"city":"chisinau","address":"s. Bacioi, lângă lacul Peatihaica","area":600,"rooms":0,"description":{"ro":"Lacul Peatihaica, Mănăstirea Cneazului Vladimir. Teren de 6 ari, proiect casă + terasă, lucrările executate se văd în fotografii. Electricitate, apă, canalizare proprie.","ru":"Озеро Пятихаика, монастырь Князя Владимира. Участок 6 соток, проект дом + терраса, выполненные работы видны на фото. Электричество, вода, собственная канализация.","en":"Near Peatihaica lake and Prince Vladimir Monastery. A 600 m² plot with a house-and-terrace project; the work done so far is shown in the photos. Electricity, water and private sewage."},"images":["/listings/ad-105577695/1.jpg","/listings/ad-105577695/2.jpg","/listings/ad-105577695/3.jpg","/listings/ad-105577695/4.jpg","/listings/ad-105577695/5.jpg"],"features":["waterView","terrace"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103907777', '{"id":"ad-103907777","title":{"ro":"1 ha cu livadă de nuci și migdali + depozit, Anenii Noi","ru":"1 га с орехом и миндалём + склад, Новые Анены","en":"1 ha walnut and almond orchard + storage, Anenii Noi"},"deal":"sale","type":"land","price":46000,"city":"aneniiNoi","address":"lângă or. Anenii Noi, la 800 m de traseu","area":10000,"rooms":0,"description":{"ro":"Lângă orașul Anenii Noi. Teren de 1 ha: 86 de nuci și 28 de migdali. Clădire de 90 m² (electricitate, apă). La 800 m de traseu.","ru":"Новые Анены, рядом с городом. Земля 1 га: 86 деревьев ореха, 28 миндаля. Здание 90 м² (электричество, вода). 800 м от трассы.","en":"Next to the town of Anenii Noi. 1 ha with 86 walnut and 28 almond trees and a 90 m² building (electricity, water). 800 m from the highway."},"images":["/listings/ad-103907777/1.jpg","/listings/ad-103907777/2.jpg","/listings/ad-103907777/3.jpg","/listings/ad-103907777/4.jpg","/listings/ad-103907777/5.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105172808', '{"id":"ad-105172808","title":{"ro":"Spațiu de 120 m² pe două niveluri în CC ELAT","ru":"Помещение 120 м² на двух уровнях в ТЦ «ЭЛАТ»","en":"120 m² two-level space in ELAT shopping centre"},"deal":"rent","type":"commercial","price":500,"city":"chisinau","address":"Centrul Comercial ELAT, bd. Decebal, Botanica","area":120,"rooms":0,"description":{"ro":"Centrul Comercial ELAT. Se dă în chirie o fostă cafenea pe două niveluri, cu lift propriu între ele. Se poate adapta pentru comerț, oficiu, servicii.","ru":"Торговый центр «ЭЛАТ». Сдаётся бывшее кафе на 2 уровнях, между уровнями свой лифт. Можно адаптировать под торговлю, офис, услуги.","en":"ELAT shopping centre. A former café on two levels with its own lift between them, for rent. Can be adapted for retail, an office or services."},"images":["/listings/ad-105172808/1.jpg","/listings/ad-105172808/2.jpg","/listings/ad-105172808/3.jpg","/listings/ad-105172808/4.jpg","/listings/ad-105172808/5.jpg","/listings/ad-105172808/6.jpg","/listings/ad-105172808/7.jpg","/listings/ad-105172808/8.jpg","/listings/ad-105172808/9.jpg"],"features":["elevator"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105578717', '{"id":"ad-105578717","title":{"ro":"2,25 ha de teren agricol în Dumbrava","ru":"225 соток под с/х в Думбраве","en":"2.25 ha of farmland in Dumbrava"},"deal":"sale","type":"land","price":1237500,"city":"chisinau","address":"Dumbrava","area":22500,"rooms":0,"description":{"ro":"5 500 € pe ar. Teren agricol de 225 de ari la marginea Dumbravei.","ru":"5 500 € за сотку. Сельхозучасток 225 соток на окраине Думбравы.","en":"€5,500 per are (100 m²). A 2.25 ha agricultural plot on the edge of Dumbrava."},"images":["/listings/ad-105578717/1.jpg","/listings/ad-105578717/2.jpg","/listings/ad-105578717/3.jpg","/listings/ad-105578717/4.jpg","/listings/ad-105578717/5.jpg","/listings/ad-105578717/6.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103639812', '{"id":"ad-103639812","title":{"ro":"Duplex pentru două familii în Pașcani, 230 și 250 m²","ru":"Дуплекс на две семьи в Пашканах, 230 и 250 м²","en":"Two-family duplex in Pașcani, 230 and 250 m²"},"deal":"sale","type":"house","price":480000,"city":"criuleni","address":"s. Pașcani, sector nou","area":480,"rooms":0,"description":{"ro":"Satul Pașcani, sector nou, la 15 minute de Chișinău. Aer foarte curat și liniște. Duplex de 230 și 250 m², materiale de calitate. 1 000 € pe m².","ru":"Посёлок Пашканы, новый сектор, 15 минут от Кишинёва. Чистый воздух и тишина. Дуплекс 230 и 250 м², качественные материалы. 1 000 € за м².","en":"Pașcani, a new residential area 15 minutes from Chișinău. Fresh air and quiet. A duplex of 230 and 250 m² built with quality materials. €1,000 per m²."},"images":["/listings/ad-103639812/1.jpg","/listings/ad-103639812/2.jpg","/listings/ad-103639812/3.jpg","/listings/ad-103639812/4.jpg","/listings/ad-103639812/5.jpg","/listings/ad-103639812/6.jpg","/listings/ad-103639812/7.jpg","/listings/ad-103639812/8.jpg","/listings/ad-103639812/9.jpg","/listings/ad-103639812/10.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104621640', '{"id":"ad-104621640","title":{"ro":"3 ha de teren de producție lângă traseu, Vatra","ru":"3 га под производство у трассы, Ватра","en":"3 ha industrial land by the highway, Vatra"},"deal":"sale","type":"land","price":650000,"city":"chisinau","address":"or. Vatra, lângă traseu","area":30000,"rooms":0,"description":{"ro":"Teren agricol de 3 ha lângă traseu, la marginea orașului Vatra.","ru":"Аграрная земля 3 га у трассы, окраина Ватры.","en":"3 ha of agricultural land by the highway on the edge of Vatra."},"images":["/listings/ad-104621640/1.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105464796', '{"id":"ad-105464796","title":{"ro":"6,5 ari lângă râu în Dănceni","ru":"6,5 сотки у речки в Данченах","en":"6.5 ares by a stream in Dănceni"},"deal":"sale","type":"land","price":36500,"city":"ialoveni","address":"s. Dănceni, str-la Luncii","area":650,"rooms":0,"description":{"ro":"6,5 ari, comunicațiile — aproape. În spatele terenului curge un râuleț: se poate amenaja un iaz și folosi mai mult teren.","ru":"6,5 сотки, коммуникации рядом. За участком протекает небольшая речка — можно организовать пруд и использовать больше земли.","en":"650 m² with utilities nearby. A small stream runs behind the plot, so a pond could be made and more land used."},"images":["/listings/ad-105464796/1.jpg","/listings/ad-105464796/2.jpg","/listings/ad-105464796/3.jpg","/listings/ad-105464796/4.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105300196', '{"id":"ad-105300196","title":{"ro":"Casă pe trei niveluri cu livadă, Alfa-Agro","ru":"Дом на три уровня с садом, Альфа Агро","en":"Three-level house with an orchard, Alfa-Agro"},"deal":"sale","type":"house","price":125000,"city":"chisinau","address":"Dumbrava, Alfa-Agro, la 15 min de Chișinău","area":150,"rooms":0,"floors":3,"description":{"ro":"Casă de țară confortabilă lângă pădure, cu livadă tânără, la 15 minute de Chișinău. Trei niveluri a câte 50 m², plus o anexă solidă. Casa e pe deal, cu priveliște frumoasă. Loc liniștit.\n\nPe teren: pomi și arbuști plantați acum 4–5 ani, deja rodesc — vișini, cireși, peri, meri, nuci, migdali, zmeură, căpșuni, gutui, pruni, viță de vie, caiși și altele. Foișor din lemn cu masă mare, loc pentru grătar. Teren de 5,5 ari cu o ușoară pantă.\n\nPentru locuire tot anul sunt necesare investiții (baie, scară între etaje; acum se încălzește doar un nivel).","ru":"Уютный загородный дом у леса с молодым садом, 15 минут от Кишинёва. Три уровня по 50 м², плюс прочная хозпостройка. Дом на холме, с участка красивый вид. Место тихое.\n\nНа участке: деревья и кустарники, посаженные 4–5 лет назад, уже плодоносят — вишня, черешня, груша, яблоня, орех, миндаль, малина, земляника, айва, слива, виноград, абрикос и другие. Деревянная беседка с большим столом, место для мангала. Участок 5,5 сотки с небольшим уклоном.\n\nДля круглогодичного проживания нужны вложения (санузел, лестница между этажами; сейчас отапливается только один уровень).","en":"A cosy country house by the forest with a young orchard, 15 minutes from Chișinău. Three levels of 50 m² each plus a solid outbuilding. The house stands on a hill with a lovely view. Quiet and peaceful.\n\nThe garden''s trees and shrubs, planted 4–5 years ago, already bear fruit — cherries, pears, apples, walnuts, almonds, raspberries, strawberries, quinces, plums, grapes, apricots and more. A wooden gazebo with a large table and a barbecue area. A 550 m² gently sloping plot.\n\nYear-round living needs some investment (bathroom, stairs between floors; only one level is heated now)."},"images":["/listings/ad-105300196/1.jpg","/listings/ad-105300196/2.jpg","/listings/ad-105300196/3.jpg","/listings/ad-105300196/4.jpg","/listings/ad-105300196/5.jpg","/listings/ad-105300196/6.jpg","/listings/ad-105300196/7.jpg","/listings/ad-105300196/8.jpg","/listings/ad-105300196/9.jpg","/listings/ad-105300196/10.jpg"],"features":["terrace"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105012776', '{"id":"ad-105012776","title":{"ro":"12 ari la intersecția din Tohatin","ru":"12 соток на перекрёстке в Тогатине","en":"12 ares at the Tohatin crossroads"},"deal":"sale","type":"land","price":65000,"city":"chisinau","address":"s. Tohatin, intersecția Tohatin – Cruzești – Budești","area":1200,"rooms":0,"description":{"ro":"Intersecția Tohatin – Cruzești – Budești, lângă Linella. Dimensiuni 12 × 100 m.","ru":"Перекрёсток Тогатин – Крузешты – Будешты, рядом Linella. Параметры 12 × 100 м.","en":"At the Tohatin – Cruzești – Budești crossroads, next to Linella. 12 × 100 m."},"images":["/listings/ad-105012776/1.jpg","/listings/ad-105012776/2.jpg","/listings/ad-105012776/3.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-104705630', '{"id":"ad-104705630","title":{"ro":"9 ari cu construcții pe str. Petricani","ru":"9 соток со строениями на ул. Петрикань","en":"9 ares with buildings on Petricani Street"},"deal":"sale","type":"land","price":140000,"city":"chisinau","address":"Rîșcani, str. Petricani","area":900,"rooms":0,"description":{"ro":"Gaz, apă, electricitate, canalizare. Construcțiile sunt proprietate privată, terenul urmează a fi privatizat. Număr cadastral 0100403.158.","ru":"Газ, вода, электричество, канализация. Строения — частная собственность, земля подлежит приватизации. Кадастровый номер 0100403.158.","en":"Gas, water, electricity and sewage. The buildings are privately owned; the land is eligible for privatisation. Cadastral number 0100403.158."},"images":["/listings/ad-104705630/1.jpg","/listings/ad-104705630/2.jpg","/listings/ad-104705630/3.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105555018', '{"id":"ad-105555018","title":{"ro":"Apartament cu 3 camere, 71 m², centrul Strășeniului","ru":"3-комнатная квартира 71 м² в центре Страшен","en":"Three-room apartment, 71 m², central Strășeni"},"deal":"sale","type":"apartment","price":71000,"city":"straseni","address":"str. Ștefan cel Mare și Sfînt, Centru","area":71,"rooms":3,"floor":7,"description":{"ro":"2 dormitoare, bucătărie, 2 băi, hol. Geamuri termopan, finisaj brut, încălzire autonomă, conectat la toate comunicațiile. Aproape: parc, grădiniță, școală, piață, restaurant Green Park, bancă, farmacii. Curte închisă, parcare și loc de joacă.","ru":"2 спальни, кухня, 2 санузла, прихожая. Стеклопакеты, черновая отделка, автономное отопление, подключена ко всем коммуникациям. Рядом парк, детский сад, школа, рынок, ресторан Green Park, банк, аптеки. Закрытый двор, парковка и детская площадка.","en":"Two bedrooms, kitchen, two bathrooms and a hallway. Double glazing, shell finish, individual heating, all utilities connected. Close to a park, kindergarten, school, market, Green Park restaurant, a bank and pharmacies. Gated courtyard with parking and a playground."},"images":["/listings/ad-105555018/1.jpg","/listings/ad-105555018/2.jpg","/listings/ad-105555018/3.jpg","/listings/ad-105555018/4.jpg","/listings/ad-105555018/5.jpg"],"features":["heating","parking"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105553489', '{"id":"ad-105553489","title":{"ro":"Spațiu de 320 m² în Artima","ru":"Помещение 320 м² в Artima","en":"320 m² space in Artima"},"deal":"rent","type":"commercial","price":5750,"city":"chisinau","address":"Artima, str. Calea Ieșilor, Sculeanca","area":320,"rooms":0,"description":{"ro":"Spațiu universal de 320 m² în Artima, str. Calea Ieșilor. Reparație pentru chiriaș.","ru":"Универсальное помещение 320 м² в Artima, ул. Калea Ешилор. Ремонт под арендатора.","en":"A 320 m² multi-purpose space in Artima on Calea Ieșilor. Fit-out to the tenant''s needs."},"images":["/listings/ad-105553489/1.jpg","/listings/ad-105553489/2.jpg","/listings/ad-105553489/3.jpg","/listings/ad-105553489/4.jpg","/listings/ad-105553489/5.jpg","/listings/ad-105553489/6.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105527372', '{"id":"ad-105527372","title":{"ro":"Spălătorie auto și service auto în Strășeni","ru":"Автомойка и автосервис в Страшенах","en":"Car wash and auto service in Strășeni"},"deal":"sale","type":"commercial","price":165000,"city":"straseni","address":"or. Strășeni","area":280,"rooms":0,"description":{"ro":"Afacere funcțională. Teren de 6 ari, construcții de 280 m².","ru":"Действующий бизнес. Участок 6 соток, строения 280 м².","en":"A running business on a 600 m² plot with 280 m² of buildings."},"images":["/listings/ad-105527372/1.jpg","/listings/ad-105527372/2.jpg","/listings/ad-105527372/3.jpg","/listings/ad-105527372/4.jpg","/listings/ad-105527372/5.jpg","/listings/ad-105527372/6.jpg","/listings/ad-105527372/7.jpg","/listings/ad-105527372/8.jpg","/listings/ad-105527372/9.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105559639', '{"id":"ad-105559639","title":{"ro":"Parte de clădire de 305 m² pe prima linie, Ciocana","ru":"Часть здания 305 м² на первой линии, Чокана","en":"305 m² of a front-line building, Ciocana"},"deal":"sale","type":"commercial","price":570000,"city":"chisinau","address":"Ciocana, str. Vadul lui Vodă","area":305,"rooms":0,"description":{"ro":"Se vinde o parte de clădire de 305 m² și 3 ari de teren. Parcare pentru 20 de mașini, prima linie. Trafic auto și pietonal intens. Construcția permite încă un nivel.","ru":"Продаётся часть здания 305 м² и 3 сотки земли. Парковка на 20 авто, первая линия. Высокий трафик машин и пешеходов. Конструкция позволяет надстроить ещё один уровень.","en":"Part of a building (305 m²) with 300 m² of land. Parking for 20 cars, right on the main road with heavy car and foot traffic. The structure allows another floor to be added."},"images":["/listings/ad-105559639/1.jpg","/listings/ad-105559639/2.jpg","/listings/ad-105559639/3.jpg","/listings/ad-105559639/4.jpg","/listings/ad-105559639/5.jpg","/listings/ad-105559639/6.jpg","/listings/ad-105559639/7.jpg","/listings/ad-105559639/8.jpg"],"features":["parking"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103688415', '{"id":"ad-103688415","title":{"ro":"Două loturi agricole de 26 și 63 ari, Dumbrava","ru":"Два сельхозучастка 26 и 63 сотки, Думбрава","en":"Two farm plots of 26 and 63 ares, Dumbrava"},"deal":"sale","type":"land","price":83000,"city":"chisinau","address":"Dumbrava","area":8900,"rooms":0,"description":{"ro":"Lot 0121204024 — 26 de ari, 31 000 €. Lot 0121204023 — 63 de ari, 70 000 €. Pentru ambele — 90 000 €.","ru":"0121204024 — 26 соток, 31 000 €. 0121204023 — 63 сотки, 70 000 €. За оба участка — 90 000 €.","en":"Plot 0121204024 — 2,600 m², €31,000. Plot 0121204023 — 6,300 m², €70,000. Both together — €90,000."},"images":["/listings/ad-103688415/1.jpg","/listings/ad-103688415/2.jpg","/listings/ad-103688415/3.jpg"],"features":[],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-103638025', '{"id":"ad-103638025","title":{"ro":"Lac cu pădure pe 6,3 ha — piscicultură, camping, odihnă","ru":"Озеро с лесом на 6,3 га — рыбоводство, кэмпинг, отдых","en":"Lake with woodland on 6.3 ha — fish farming, camping, leisure"},"deal":"sale","type":"land","price":185000,"exchangeFor":{"ro":"Schimb parțial pe automobil sau imobil.","ru":"Частичный обмен на автомобиль или недвижимость.","en":"Partial exchange for a car or property."},"city":"orhei","address":"lângă s. Ivancea, direcția Orheiul Vechi","area":63000,"rooms":0,"description":{"ro":"Un loc foarte frumos! Permite creșterea peștelui și amenajarea unei zone de odihnă. Lacul e înconjurat de pădure. Direcția turistică Orheiul Vechi, lângă satul Ivancea, la 35 km de Chișinău. Drum bun până la baraj.\n\nAcum apa e puțină: lacul se alimentează din izvoare, iar în preț e inclusă o fântână arteziană planificată. Acces la electricitate, gaz și apeduct. Suprafața totală — 6,3 ha.","ru":"Очень красивое место! Можно разводить рыбу и обустроить зону отдыха. Озеро окружено лесом. Туристическое направление Орхей Векь, в районе села Иванча, 35 км от Кишинёва. Хорошая дорога до плотины.\n\nСейчас воды мало: озеро питается родниками, в цену включён планируемый артезианский колодец. Доступ к электричеству, газу и центральному водоснабжению. Общая площадь — 6,3 га.","en":"A beautiful spot for fish farming and a leisure area, with the lake surrounded by forest. On the Old Orhei tourist route near Ivancea, 35 km from Chișinău, with a good road to the dam.\n\nThe water level is low for now: the lake is spring-fed, and a planned artesian well is included in the price. Electricity, gas and mains water available. 6.3 ha in total."},"images":["/listings/ad-103638025/1.jpg","/listings/ad-103638025/2.jpg","/listings/ad-103638025/3.jpg","/listings/ad-103638025/4.jpg","/listings/ad-103638025/5.jpg","/listings/ad-103638025/6.jpg","/listings/ad-103638025/7.jpg","/listings/ad-103638025/8.jpg","/listings/ad-103638025/9.jpg","/listings/ad-103638025/10.jpg"],"features":["waterView"],"contactName":"","contactPhone":"","createdAt":"2026-10-31","featured":true}', 'active', '2026-10-31');
INSERT OR IGNORE INTO listings (id, data, status, created_at) VALUES ('ad-105029151', '{"id":"ad-105029151","title":{"ro":"Casă de vacanță cu 8 ari lângă plaja Ghidighici","ru":"Дом-дача на 8 сотках у пляжа Гидигич","en":"Holiday house on 8 ares near Ghidighici beach"},"deal":"sale","type":"house","price":90000,"city":"chisinau","address":"or. Vatra, la 15 min pe jos de plaja Ghidighici","area":90,"rooms":0,"description":{"ro":"Casă-vilă de 90 m², beci, terasă. Teren de 8 ari. 15 minute pe jos până la plaja Ghidighici.","ru":"Дом-дача 90 м², погреб, терраса. Участок 8 соток. 15 минут пешком до пляжа Гидигич.","en":"A 90 m² holiday house with a cellar and terrace on an 800 m² plot. A 15-minute walk to Ghidighici beach."},"images":["/listings/ad-105029151/1.jpg","/listings/ad-105029151/2.jpg","/listings/ad-105029151/3.jpg","/listings/ad-105029151/4.jpg","/listings/ad-105029151/5.jpg","/listings/ad-105029151/6.jpg","/listings/ad-105029151/7.jpg","/listings/ad-105029151/8.jpg","/listings/ad-105029151/9.jpg","/listings/ad-105029151/10.jpg"],"features":["terrace"],"contactName":"","contactPhone":"","createdAt":"2026-10-31"}', 'active', '2026-10-31');
